def rle_encode(text):
    pieces = []
    i = 0
    while i < len(text):
        j = i
        while j < len(text) and text[j] == text[i]:
            j += 1                             # j ends just past the run that starts at i
        pieces.append(f"{text[i]}{j - i}")
        i = j
    return "".join(pieces)


def rle_decode(encoded):
    pieces = []
    i = 0
    while i < len(encoded):
        char = encoded[i]
        i += 1
        start = i
        while i < len(encoded) and encoded[i].isdigit():
            i += 1                             # the count may have several digits
        pieces.append(char * int(encoded[start:i]))
    return "".join(pieces)
